mapper.select:
SELECT "bd"."bus_stop_departure_time" AS "busStopDepartureTime" , "d"."operation_cancel_flg" AS "operationCancelFlg" , "d"."sales_cancel_flg" AS "salesCancelFlg" , "d"."service_date" AS "serviceDate" , "d"."vehicle_id" AS "vehicleId" , "d"."vehicle_id" AS "VehicleName" , "d"."notification" AS "notification" , "l"."rosen_name" AS "rosenName" , "lr"."line_detail_service_division" AS "lineDetailServiceDivision" , "lr"."line_route_name" AS "lineRouteName" , "oc"."operating_name" AS "operatingCompanyName" , EXTRACT(EPOCH FROM (service_date::timestamp + time '00:00:00'))::bigint AS service_start_time , EXTRACT(EPOCH FROM (service_date::timestamp + time '23:59:59'))::bigint AS service_end_time , "bs".bus_service_trip_id AS "busServiceTripid" FROM "daily_bus_daiyas" "d" INNER JOIN "bus_services" "bs" ON "bs"."del_flag" = 0 AND "bs"."bus_service_id" = "d"."bus_service_id" INNER JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "d"."bus_service_id" INNER JOIN "line_route_bus_stops" "lrb" ON "lrb"."del_flag" = 0 AND "lrb"."line_route_bus_stop_id" = "bd"."line_route_bus_stop_id" INNER JOIN "signposts" "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrb"."signpost_id" INNER JOIN "line_routes" "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "lrb"."line_route_id" INNER JOIN "lines" "l" ON "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "l"."rosen_id" = "lr"."rosen_id" INNER JOIN "agencies" "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "l"."business_corp_id" LEFT JOIN "offices" "o" ON "o"."del_flag" = 0 AND "o"."available_flag" = 1 AND "o"."office_id" = "bs"."office_id" LEFT JOIN "operating_companies" "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1 AND "oc"."operating_company_id" = "o"."operating_company_id" WHERE "d"."del_flag" = 0 AND "d"."daily_bus_daiya_id" = #{dailyBusDaiyaId} AND "l"."business_corp_id" = #{businessCorpId}
AND "oc"."operating_company_id" = #{operatingCompanyId}
AND "lr"."line_detail_service_division" = #{lineDetailServiceDivision}
AND "l"."rosen_id" = #{rosenId}
ORDER BY "lrb"."stop_sequence" ASC LIMIT 1

SELECT "bd"."bus_stop_departure_time" , "lrb"."ride_alight_division" , "lrb"."drop_off_division" , "lrb"."stop_sequence" , "sp"."signpost_name" FROM "daily_bus_daiyas" "d" INNER JOIN "bus_services" "bs" ON "bs"."bus_service_id" = "d"."bus_service_id" AND "bs"."del_flag" = 0 INNER JOIN "bus_daiyas" "bd" ON "bd"."bus_service_id" = "d"."bus_service_id" AND "bd"."del_flag" = 0 INNER JOIN "line_route_bus_stops" "lrb" ON "lrb"."line_route_bus_stop_id" = "bd"."line_route_bus_stop_id" AND "lrb"."del_flag" = 0 INNER JOIN "signposts" "sp" ON "sp"."signpost_id" = "lrb"."signpost_id" AND "sp"."available_flag" = 1 AND "sp"."del_flag" = 0 INNER JOIN "line_routes" "lr" ON "lr"."line_route_id" = "lrb"."line_route_id" AND "lr"."available_flag" = 1 AND "lr"."del_flag" = 0 INNER JOIN "lines" "l" ON "l"."rosen_id" = "lr"."rosen_id" AND "l"."available_flag" = 1 AND "l"."del_flag" = 0 INNER JOIN "agencies" "ag" ON "ag"."business_corp_id" = "l"."business_corp_id" AND "ag"."available_flag" = 1 AND "ag"."del_flag" = 0 LEFT JOIN "offices" "o" ON "o"."office_id" = "bs"."office_id" AND "o"."available_flag" = 1 AND "o"."del_flag" = 0 LEFT JOIN "operating_companies" "oc" ON "oc"."operating_company_id" = "o"."operating_company_id" AND "oc"."available_flag" = 1 AND "oc"."del_flag" = 0 WHERE "d"."del_flag" = 0 AND "d"."daily_bus_daiya_id" = #{dailyBusDaiyaId} AND "l"."business_corp_id" = #{businessCorpId}
AND "oc"."operating_company_id" = #{operatingCompanyId}
AND "lr"."line_detail_service_division" = #{lineDetailServiceDivision}
AND "l"."rosen_id" = #{rosenId}
AND "bd"."bus_stop_departure_time" = to_char(CAST(#{busStopDepartureTime} AS time), 'HH24:MI:SS')

SELECT COUNT(1) FROM "daily_bus_daiyas" "d" INNER JOIN "bus_services" "bs" ON "bs"."del_flag" = 0 AND "bs"."bus_service_id" = "d"."bus_service_id" INNER JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "d"."bus_service_id" INNER JOIN "line_route_bus_stops" "lrb" ON "lrb"."del_flag" = 0 AND "lrb"."line_route_bus_stop_id" = "bd"."line_route_bus_stop_id" INNER JOIN "signposts" "sp" ON "sp"."del_flag" = 0 AND "sp"."available_flag" = 1 AND "sp"."signpost_id" = "lrb"."signpost_id" INNER JOIN "line_routes" "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "lrb"."line_route_id" INNER JOIN "lines" "l" ON "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "l"."rosen_id" = "lr"."rosen_id" INNER JOIN "agencies" "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "l"."business_corp_id" LEFT JOIN "offices" "o" ON "o"."del_flag" = 0 AND "o"."available_flag" = 1 AND "o"."office_id" = "bs"."office_id" LEFT JOIN "operating_companies" "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1 AND "oc"."operating_company_id" = "o"."operating_company_id" WHERE "d"."del_flag" = 0 AND "d"."daily_bus_daiya_id" = #{dailyBusDaiyaId} AND "l"."business_corp_id" = #{businessCorpId}
AND "oc"."operating_company_id" = #{operatingCompanyId}
AND "lr"."line_detail_service_division" = #{lineDetailServiceDivision}
AND "l"."rosen_id" = #{rosenId}

mapper.sql:
FROM "lines" "l" INNER JOIN "agencies" "ag" ON "ag"."del_flag" = 0 AND "ag"."available_flag" = 1 AND "ag"."business_corp_id" = "l"."business_corp_id" INNER JOIN "daiya_revisions" "dr" ON "dr"."del_flag" = 0 AND "dr"."rosen_id" = "l"."rosen_id" INNER JOIN "bus_services" "bs" ON "bs"."del_flag" = 0 AND "bs"."daiya_revision_id" = "dr"."daiya_revision_id" LEFT JOIN "daily_bus_daiyas" "d" ON "d"."del_flag" = 0 AND "d"."bus_service_id" = "bs"."bus_service_id" INNER JOIN "bus_daiyas" "bd" ON "bd"."del_flag" = 0 AND "bd"."bus_service_id" = "bs"."bus_service_id" INNER JOIN "line_routes" "lr" ON "lr"."del_flag" = 0 AND "lr"."available_flag" = 1 AND "lr"."line_route_id" = "bs"."line_route_id"
INNER JOIN "offices" "o" ON "o"."del_flag" = 0 AND "o"."available_flag" = 1 AND "o"."operating_company_id" = #{operatingCompanyId} AND "o"."office_id" = "bs"."office_id" INNER JOIN "operating_companies" "oc" ON "oc"."del_flag" = 0 AND "oc"."available_flag" = 1 AND "oc"."operating_company_id" = "o"."operating_company_id"
WHERE "l"."del_flag" = 0 AND "l"."available_flag" = 1 AND "ag"."business_corp_id" = #{businessCorpId}
AND "l"."rosen_id" = #{rosenId}
AND "lr"."line_route_id" = #{lineRouteId}
AND "d"."service_date" >= CAST(#{serviceStartDate} AS date)
AND "d"."service_date" <= CAST(#{serviceEndDate} AS date)
AND "d"."sales_cancel_flg" = #{salesCancelFlg}
AND "bd"."bus_stop_departure_time" = ( SELECT MIN("bd2"."bus_stop_departure_time") FROM "bus_daiyas" "bd2" WHERE "bd2"."bus_service_id" = "bs"."bus_service_id" AND "bd2"."del_flag" = 0 )
AND "bd"."bus_stop_departure_time" >= #{busStopDepartureTimeStart}
AND "bd"."bus_stop_departure_time" <= #{busStopDepartureTimeEnd}
AND "bs"."bus_service_id" = #{busServiceId}

mapper.insert:
INSERT INTO "daily_bus_daiyas" (
       "bus_service_id"
     , "service_date"
     , "sales_cancel_flg"
     , "operation_cancel_flg"
     , "vehicle_id"

)
VALUES (
       #{busServiceId}
     , CAST(#{serviceDate} AS date)
     , #{salesCancelFlg}
     , #{operationCancelFlg}
     , #{vehicleId}

)
